  internal static void InitializePlacementDetails() {
    for (int index = 0; index < _entries.Length; index++) {
      ItemID.Sets.DerivedPlacementDetails[index].tileType = _entries[index].createTile;
      ItemID.Sets.DerivedPlacementDetails[index].tileStyle = checked((short)_entries[index].placeStyle);
    }
  }

  internal static void Apply(Item item) {
    Entry entry = _entries[item.type];
    item.createTile = entry.createTile;
    item.placeStyle = entry.placeStyle;
    item.fishingPole = entry.fishingPole;
    item.rare = entry.rare;
    item.damage = entry.damage;
    item.useAnimation = entry.useAnimation;
    item.useTime = entry.useTime;
    item.reuseDelay = entry.reuseDelay;
    item.mana = entry.mana;
    item.crit = entry.crit;
    item.value = entry.value;
    item.knockBack = entry.knockBack;
    item.scale = entry.scale;
    item.shootSpeed = entry.shootSpeed;
    item.accessory = (entry.Flags & 1) != 0;
    item.melee = (entry.Flags & 2) != 0;
    item.vanity = (entry.Flags & 4) != 0;
  }
}
